import Foundation

/// Files under `Tests/DMCoreTests/Fixtures`, captured from the real hub or generated by the real JS.
enum Fixture {
    static func url(_ path: String) -> URL {
        Bundle.module.resourceURL!.appendingPathComponent("Fixtures").appendingPathComponent(path)
    }

    static func data(_ path: String) throws -> Data {
        try Data(contentsOf: url(path))
    }

    static func string(_ path: String) throws -> String {
        String(decoding: try data(path), as: UTF8.self)
    }
}
